.time {
    font-size: 14px;
    font-weight: 400;
    line-height: 20px;
    text-align: left;
    color: #667085;
}

.text {
    font-size: 16px;
    font-weight: 400;
    line-height: 24px;
    text-align: left;
    color: #0C111D;
}

.timeline-container {
  position: relative;
  margin-left: 20px;
  border-left: 2px solid #026AA2;
  padding-left: 20px;
}

.timeline-event {
  position: relative;
  margin-bottom: 20px;
  padding-left: 20px;
}

.timeline-event:last-child {
  margin-bottom: 0;
}

.event-dot {
  position: absolute;
  top: 0;
  left: -30px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  /*border: 2px solid #fff;*/
  /*background-color: #007bff;*/
}

